def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opD = op.count('D')
    myD = my.count('D')
    last_me = my[-1]
    last_op = op[-1]

    if opD == 0:
        if n >= 98:
            return 'D'
        return 'C'

    if opD == n:
        if rng.random() < 0.02:
            return 'C'
        return 'D'

    remaining = 100 - n
    if remaining <= 1:
        return 'D'
    if remaining <= 3:
        if last_op == 'D' or opD * 2 > n:
            return 'D'
        return 'C'

    recent = op[-6:]
    recent_d = sum(1 for x in recent if x == 'D')
    recent_c = len(recent) - recent_d

    if n >= 4 and op[-4:].count('D') >= 3:
        return 'D'

    if last_op == 'D':
        if last_me == 'D' and recent_d <= 2:
            return 'C'
        return 'D'

    if last_me == 'D':
        if last_op == 'C':
            return 'C'

    if n >= 8 and recent_c >= 5:
        if n >= 10 and n % 9 == 0:
            return 'D'
        return 'C'

    if recent_d >= 3:
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    if opD * 3 <= n:
        return 'C'

    if rng.random() < 0.7:
        return 'C'
    return 'D'
